UISparkleImage=function(game){Phaser.Image.call(this,game,0,0,'game','sparkle');this.anchor.setTo(0.5,0.5);this.scale.setTo(UIConstants.GAME_ASSET_SCALE,UIConstants.GAME_ASSET_SCALE);this.kill();};UISparkleImage.prototype=Object.create(Phaser.Image.prototype);UISparkleImage.prototype.constructor=UISparkleImage;UISparkleImage.prototype.update=function(){if(!this.exists){return;}};UISparkleImage.prototype.spawn=function(x,y){this.reset(x,y);this.scale.setTo(0.01,0.01);this.sizeTween=this.game.add.tween(this.scale);this.sizeTween.to({x:UIConstants.GAME_ASSET_SCALE,y:UIConstants.GAME_ASSET_SCALE},UIConstants.SPARKLE_ANIMATION_TIME,Phaser.Easing.Linear.None,false);this.sizeTween.to({x:0.01,y:0.01},UIConstants.SPARKLE_ANIMATION_TIME,Phaser.Easing.Linear.None,true);this.sizeTween.onComplete.add(function(){this.kill();},this);this.rotation=Math.random()*Math.PI;this.rotationTween=this.game.add.tween(this).to({rotation:this.rotation+Math.PI},2*UIConstants.SPARKLE_ANIMATION_TIME,Phaser.Easing.Linear.None,true);};UISparkleImage.prototype.remove=function(){if(this.sizeTween){this.sizeTween.stop();}if(this.rotationTween){this.rotationTween.stop();}this.kill();};UISparkleImage.prototype.retire=function(){if(this.rotationTween){this.rotationTween.stop();}this.kill();};